  private StructClass tryLoadClass(final DuplicateClassResolver.Selection selection, final String key) {
    try {
      DecompilerContext.getLogger().writeMessage("Loading Class: " + key + " from " + selection.unit.getName(), IFernflowerLogger.Severity.INFO);
      StructClass clazz = StructClass.create(new DataInputFullStream(selection.bytes), selection.unit.isOwn());
      if (clazz == null) {
        return null;
